mapper.select:
SELECT
IFNULL(SUM(wr.quantity),0) quantity,

    
        IFNULL(SUM(a.net_weight * wr.quantity),0) mete
        FROM mes_building_warehouse_record wr
        INNER JOIN tech_artifact a ON a.id = wr.product_id AND wr.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
    
    
        IFNULL(SUM(e.length * wr.quantity),0) mete
        FROM mes_building_warehouse_record wr
        INNER JOIN tech_enclosure e ON e.id = wr.product_id AND wr.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}
    


    and wr.bool_delete_enum = 0
    
        AND wr.project_id in
        
            #{projectId}
        
    
    
        AND wr.project_id=#{projectId}
    
    
        AND wr.factory_id = #{factoryId}
    
    
        AND wr.type = #{type}
    
    
        and date(wr.create_time) >= date(#{startDate})
    
    
        and date(wr.create_time) <= date(#{endDate})

SELECT a.id 'area.id', a.name 'area.name', a.product_type 'area.product_type', IFNULL( quantity, 0 ) quantity, IFNULL( mete, 0 ) mete, IFNULL( dispatch_quantity, 0 ) dispatch_quantity, IFNULL( dispatch_mete, 0 ) dispatch_mete FROM plan_area a LEFT JOIN ( SELECT a.area_id, IFNULL(sum(a.quantity),0) quantity,
IFNULL(sum(a.quantity*a.net_weight),0) IFNULL(sum(a.quantity*a.length),0) mete, IFNULL(sum(a.dispatch_quantity),0) dispatch_quantity,
IFNULL(sum(a.dispatch_quantity*a.net_weight),0) IFNULL(sum(a.dispatch_quantity*a.length),0) dispatch_mete FROM ( SELECT product.*, complete.* FROM
tech_artifact tech_enclosure product LEFT JOIN ( SELECT product_id, sum( quantity ) dispatch_quantity FROM mes_building_warehouse_record
product_type = #{productType} AND type=${@com.hzchum.scim.mes.building.core.api.enums.WarehouseTypeEnum@OUT.getType()} and bool_delete_enum = 0
AND project_id=#{projectId}
AND monomer_id=#{monomerId}
GROUP BY product_id ) AS complete ON complete.product_id = product.id LEFT JOIN plan_area area ON area.id= product.area_id AND area.bool_delete_enum = 0
product.bool_delete_enum = 0
AND product.project_id=#{projectId}
AND product.monomer_id=#{monomerId}
) AS a GROUP BY a.area_id) AS b ON a.id=b.area_id WHERE
a.product_type =1 a.product_type !=1
AND a.bool_delete_enum = 0 AND project_id = #{projectId} AND monomer_id = #{monomerId}

SELECT mbc.team_id teamId, mbc.product_id productId, mbc.task_type_enum productType, mpl.NAME productionLineName, cp.NAME projectName, cp.short_name shortName, cp.id projectId, pm.NAME monomerName, pm.id monomerId, pa.NAME areaName, pa.id areaId, mbt.id taskId, ta.serial_number serialNumber, ta.NAME productName, IFNULL( SUM( mbc.quantity ), 0 ) quantity, mbt.print_quantity printQuantity, MAX(mbc.create_time) time FROM mes_building_complete mbc LEFT JOIN mes_building_production_line mpl ON mbc.production_line_id = mpl.id AND mpl.bool_delete_enum = 0 AND mpl.bool_enabled_enum = 1 LEFT JOIN contract_project cp ON mbc.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN plan_monomer pm ON mbc.monomer_id = pm.id AND pm.bool_delete_enum = 0 LEFT JOIN plan_area pa ON mbc.area_id = pa.id AND pa.bool_delete_enum = 0 LEFT JOIN tech_artifact ta ON mbc.product_id = ta.id AND ta.bool_delete_enum = 0 LEFT JOIN mes_building_task mbt ON mbc.task_id = mbt.id AND mbt.bool_delete_enum = 0 WHERE mbc.bool_delete_enum = 0
AND date_format( mbc.create_time, '%Y/%m/%d' ) = date_format( #{dateTime}, '%Y/%m/%d' )
AND mpl.name like concat('%',#{productionLineName},'%')
AND ta.NAME like concat('%',#{productName},'%')
AND mbc.project_id = #{projectId}
AND mbc.monomer_id = #{monomerId}
AND mbc.area_id = #{areaId}
AND ta.serial_number like concat('%',#{serialNumber},'%')
AND mbc.task_type_enum=#{productType}
GROUP BY mbc.team_id, mbc.product_id, mbc.task_type_enum, mpl.NAME , cp.NAME , cp.short_name, cp.id , pm.NAME , pm.id , pa.NAME , pa.id , ta.serial_number , ta.NAME , mbt.id, mbt.print_quantity ORDER BY time DESC

select project.name AS 'project.name', a.project_id AS 'project.id', project.short_name AS 'project.shortName', a.monomer_id AS 'monomer.id', m.name AS 'monomer.name', a.area_id AS 'area.id', pa.name AS 'area.name', a.name, '构件' AS typeName, a.serial_number, a.specification, a.length, a.material, a.net_weight, a.bool_all_part_send_directly, a.gross_weight, sum(packLink.quantity) AS quantity, sum(ifnull(packLink.quantity,0) * ifnull(a.net_weight,0)) AS totalNetWeight, sum(ifnull(packLink.quantity,0) * ifnull(a.gross_weight,0)) AS totalGrossWeight, pack.serial_number AS packSerialNumber from mes_building_package_link packLink INNER JOIN mes_building_package pack on pack.id = packLink.package_id and pack.id and pack.status = 0 and pack.bool_delete_enum = 0 and pack.product_type = 2 LEFT JOIN tech_artifact a on a.id = packLink.product_id and a.bool_delete_enum = 0 left join plan_monomer m on m.id = a.monomer_id left join plan_area pa on pa.id = a.area_id left join contract_project project on project.id = a.project_id where packLink.bool_delete_enum = 0 and packLink.product_type = 2
and packLink.project_id = #{projectId}
AND packLink.monomer_id = #{monomerId}
AND packLink.area_id = #{areaId}
AND packLink.workshop_id = #{workshopId}
AND packLink.in_year_month_day_date >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND packLink.in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
GROUP BY a.project_id, project.name, project.short_name, m.name, pa.name, a.monomer_id, a.area_id, a.serial_number, a.bool_all_part_send_directly, a.specification, a.length, a.material, a.net_weight, a.gross_weight, a.NAME, pack.serial_number

select * from ( select project.name AS 'project.name', project.id AS 'project.id', project.short_name AS 'project.shortName', project.serial_number AS 'project.serialNumber', pa.id 'area.id', pa.`name` 'area.name', a.serial_number, a.name, a.plate, a.length, a.surface_area,
ifnull(temp1.in_quantity,0) quantity, ifnull(temp1.in_quantity,0) * a.length totalLength, ifnull(temp1.in_quantity,0) * a.surface_area totalArea, temp1.create_time createTime,
ifnull(temp2.out_quantity,0) quantity, ifnull(temp2.out_quantity,0) * a.length totalLength, ifnull(temp2.out_quantity,0) * a.surface_area totalArea, temp2.create_time,
a.category from tech_enclosure a LEFT JOIN enclosure_plan pa ON a.enclosure_plan_id = pa.id AND pa.bool_delete_enum = FALSE
left join (select product_id, quantity in_quantity, create_time from mes_building_warehouse_record where product_type = #{productType} and type = 1
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) = DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
) temp1 on temp1.product_id = a.id
left join (select product_id, quantity out_quantity, create_time from mes_building_warehouse_record where product_type = #{productType} and type = 2
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) = DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
) temp2 on temp2.product_id = a.id
LEFT JOIn contract_project project on project.id = a.project_id
and a.project_id = #{projectId}
and a.enclosure_plan_id = #{enclosurePlanId}
and a.serial_number like concat('%', #{serialNumber}, '%')
and a.bool_delete_enum = 0
AND a.category = #{category}
AND a.dictionary_id = #{dictionaryId}
) a where a.quantity > 0

select a.* from (
select project.name AS 'project.name', project.id AS 'project.id', project.short_name AS 'project.shortName', project.serial_number AS 'project.serialNumber', m.`id` 'monomer.id', m.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name',
a.`name` name, '构件' AS typeName,
a.`name` name, case a.bool_all_part_send_directly when 0 then '直发件' else '直发檩条' END typeName,
a.serial_number, a.specification, a.length, a.material, a.net_weight, a.bool_all_part_send_directly, a.gross_weight, ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) quantity, ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0)),0) *a.net_weight totalNetWeight, ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0)),0) *a.gross_weight totalGrossWeight from
tech_artifact a
tech_assemble a
tech_machine_part a
left join plan_monomer m on m.id = a.monomer_id left join plan_area pa on pa.id = a.area_id LEFT JOIn contract_project project on project.id = a.project_id left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) temp1 on temp1.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND date_format(create_time, '%Y-%m-%d') <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) temp2 on temp2.product_id = a.id
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
and a.serial_number like concat('%', #{serialNumber}, '%')
and a.bool_delete_enum = 0
) a where a.quantity > 0

select * from ( select project.name AS 'project.name', project.id AS 'project.id', project.short_name AS 'project.shortName', project.serial_number AS 'project.serialNumber', pa.id 'area.id', pa.`name` 'area.name', a.serial_number, a.name, a.category, a.plate, a.length, a.surface_area, ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) quantity, ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0)),0) *a.length totalLength, ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0)),0) * a.surface_area totalArea from tech_enclosure a LEFT JOIn contract_project project on project.id = a.project_id LEFT JOIN enclosure_plan pa ON a.enclosure_plan_id = pa.id AND pa.bool_delete_enum = FALSE left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) temp1 on temp1.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) temp2 on temp2.product_id = a.id
and a.project_id = #{projectId}
and a.enclosure_plan_id = #{enclosurePlanId}
and a.serial_number like concat('%', #{serialNumber}, '%')
and a.bool_delete_enum = 0
AND a.category = #{category}
AND a.dictionary_id = #{dictionaryId}
) a where a.quantity > 0

select a.* from (
select project.name AS 'project.name', project.id AS 'project.id', project.short_name AS 'project.shortName', project.serial_number AS 'project.serialNumber', m.`id` 'monomer.id', m.`name` 'monomer.name', pa.id 'area.id', pa.`name` 'area.name',
a.`name` name, '构件' AS typeName,
a.`name` name, case a.bool_all_part_send_directly when 0 then '直发件' else '直发檩条' END typeName,
a.serial_number, a.specification, a.length, a.material, a.net_weight, a.bool_all_part_send_directly, a.gross_weight, ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) - ifnull(i.in_quantity,0) + ifnull(o.out_quantity,0) quantity , ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) - ifnull(i.in_quantity,0) + ifnull(o.out_quantity,0)),0) * a.net_weight totalNetWeight, ifnull((ifnull( temp1.in_quantity, 0 ) - ifnull( temp2.out_quantity, 0 ) - ifnull( i.in_quantity, 0 ) + ifnull( o.out_quantity, 0 )),0) *a.gross_weight totalGrossWeight from
tech_artifact a
tech_assemble a
tech_machine_part a
left join plan_monomer m on m.id = a.monomer_id left join plan_area pa on pa.id = a.area_id LEFT JOIn contract_project project on project.id = a.project_id left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) temp1 on temp1.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) temp2 on temp2.product_id = a.id
left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND in_year_month_day_date >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) i on i.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2 and warehouse_type in(0,2)
and project_id = #{projectId}
and bool_delete_enum = 0
AND in_year_month_day_date >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')
AND workshop_id = #{workshopId}
group by product_id ) o on o.product_id = a.id
and a.project_id = #{projectId}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
and a.serial_number like concat('%', #{serialNumber}, '%')
and a.bool_delete_enum = 0
) a where a.quantity > 0

select * from ( select project.name AS 'project.name', project.id AS 'project.id', project.short_name AS 'project.shortName', project.serial_number AS 'project.serialNumber', pa.id 'area.id', pa.`name` 'area.name', a.serial_number, a.name, a.category, a.plate, a.length, a.surface_area, ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) - ifnull(i.in_quantity,0) + ifnull(o.out_quantity,0) quantity , ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) - ifnull(i.in_quantity,0) + ifnull(o.out_quantity,0)),0) * a.length totalLength, ifnull((ifnull(temp1.in_quantity,0) - ifnull(temp2.out_quantity,0) - ifnull(i.in_quantity,0) + ifnull(o.out_quantity,0)),0) * a.surface_area totalArea from tech_enclosure a LEFT JOIn contract_project project on project.id = a.project_id LEFT JOIN enclosure_plan pa ON a.enclosure_plan_id = pa.id AND pa.bool_delete_enum = FALSE left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) temp1 on temp1.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) <= DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) temp2 on temp2.product_id = a.id
left join (select product_id, sum(quantity) in_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 1
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) = DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) i on i.product_id = a.id left join (select product_id, sum(quantity) out_quantity from mes_building_warehouse_record where product_type = #{productType} and type = 2
and project_id = #{projectId}
and bool_delete_enum = 0
AND DATE_FORMAT(create_time, '%Y-%m' ) = DATE_FORMAT( #{dateTime}, '%Y-%m' )
AND workshop_id = #{workshopId}
group by product_id ) o on o.product_id = a.id
and a.project_id = #{projectId}
and a.enclosure_plan_id = #{enclosurePlanId}
and a.serial_number like concat('%', #{serialNumber}, '%')
and a.bool_delete_enum = 0
AND a.category = #{category}
AND a.dictionary_id = #{dictionaryId}
) a where a.quantity > 0

SELECT summary.id, summary.product_id 'artifactId', c.id, IF ( log.old_quantity IS NULL, summary.quantity, log.old_quantity ) 'oldQuantity', IF ( log.quantity IS NULL, summary.quantity, log.quantity ) 'newQuantity', art.material 'material', art.length 'length', art.name 'name', art.serial_number 'serialNumber', art.specification 'specification', c.old_net_weight 'oldNetWeight', c.new_net_weight 'newNetWeight', c.old_gross_weight 'oldGrossWeight', c.new_gross_weight 'newGrossWeight', (IF( log.old_quantity IS NULL, summary.quantity, log.old_quantity ) * c.old_net_weight) totalOldNetWeight, (IF( log.quantity IS NULL, summary.quantity, log.quantity ) * c.new_net_weight) totalNewNetWeight, pro.id 'project.id', pro.name 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serial_number', mon.id 'monomer.id', mon.name 'monomer.name', area.id 'area.id', area.name 'area.name' FROM tech_artifact_change c LEFT JOIN mes_building_change_log log ON log.change_id = c.id AND log.bool_delete_enum = 0 AND log.type = 1 AND log.task_type_enum = 2 LEFT JOIN mes_building_warehouse_summary summary ON log.table_id = summary.id LEFT JOIN tech_artifact art ON summary.product_id = art.id LEFT JOIN contract_project pro ON art.project_id = pro.id LEFT JOIN plan_monomer mon ON art.monomer_id = mon.id LEFT JOIN plan_area area ON art.area_id = area.id WHERE c.bool_delete_enum = 0
AND c.id IN
#{id}

SELECT record.id, record.product_id 'artifactId', c.id, record.quantity 'oldQuantity', record.quantity 'newQuantity', art.material 'material', art.length 'length', art.name 'name', art.serial_number 'serialNumber', art.specification 'specification', c.old_net_weight 'oldNetWeight', c.new_net_weight 'newNetWeight', c.old_gross_weight 'oldGrossWeight', c.new_gross_weight 'newGrossWeight', (record.quantity * c.old_net_weight) totalOldNetWeight, (record.quantity * c.new_net_weight) totalNewNetWeight, pro.id 'project.id', pro.name 'project.name', pro.short_name 'project.shortName', pro.serial_number 'project.serial_number', mon.id 'monomer.id', mon.name 'monomer.name', area.id 'area.id', area.name 'area.name' FROM mes_building_warehouse_record record LEFT JOIN tech_artifact_change c ON record.product_id = c.artifact_id AND record.create_time < c.handle_time LEFT JOIN tech_artifact art ON record.product_id=art.id LEFT JOIN contract_project pro ON art.project_id=pro.id LEFT JOIN plan_monomer mon ON art.monomer_id=mon.id LEFT JOIN plan_area area ON art.area_id=area.id WHERE c.bool_delete_enum = 0 AND record.bool_delete_enum = 0
AND c.id IN
#{id}

SELECT c.NAME AS monomerName, d.NAME AS areaName, a.product_id AS productId, a.quantity AS productionNumber, b.`name` AS productName, b.serial_number AS serialNumber, b.specification AS specification, b.length AS length, b.material AS material, a.quantity * b.net_weight AS weight, DATE_FORMAT( a.create_time, '%Y-%m-%d' ) AS createTime FROM mes_building_warehouse_record a INNER JOIN tech_artifact b ON a.product_id = b.id INNER JOIN plan_monomer c ON a.monomer_id = c.id INNER JOIN plan_area d ON a.area_id = d.id WHERE a.product_type = 2 AND a.type = 1 AND a.bool_delete_enum = 0 AND b.bool_delete_enum = 0 AND c.bool_delete_enum = 0 AND d.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.workshop_id = #{workShopId}
and date(a.create_time) >= date(#{startDate})
and date(a.create_time) <= date(#{endDate})
AND DATE_FORMAT(a.create_time,'%Y') = #{year}

SELECT sum(a.quantity * b.net_weight) AS weight FROM mes_building_warehouse_record a INNER JOIN tech_artifact b ON a.product_id = b.id INNER JOIN plan_monomer c ON a.monomer_id = c.id INNER JOIN plan_area d ON a.area_id = d.id WHERE a.product_type = 2 AND a.type = 1 AND a.bool_delete_enum = 0 AND b.bool_delete_enum = 0 AND c.bool_delete_enum = 0 AND d.bool_delete_enum = 0
AND a.project_id = #{projectId}
AND a.workshop_id = #{workShopId}
and date(a.create_time) >= date(#{startDate})
and date(a.create_time) <= date(#{endDate})
AND DATE_FORMAT(a.create_time,'%Y') = #{year}

SELECT cp.serial_number, cp.short_name, sum( rec.quantity ) completeQuantity, sum( rec.quantity * art.net_weight ) completeWeightSum FROM mes_building_warehouse_record rec LEFT JOIN tech_artifact art ON rec.product_id = art.id AND art.bool_delete_enum = 0 left join contract_project cp on art.project_id = cp.id and cp.bool_delete_enum = 0 WHERE rec.bool_delete_enum = 0 AND rec.product_type = 2 AND rec.type = 1 and DATE_FORMAT(rec.create_time,'%Y-%m') = DATE_FORMAT(#{date},'%Y-%m')
and rec.workshop_id = #{workshopId}
GROUP BY cp.serial_number, cp.short_name
